#include <iostream>
#include <string>

class SimpleDate {
private:
    int month;
    int day;
    int year;

    static bool isLeapYear(int y) {
        return (y % 400 == 0) || (y % 100 != 0 && y % 4 == 0);
    }

    static int daysInMonth(int m, int y) {
        const int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (m == 2 && isLeapYear(y)) return 29;
        return days[m];
    }

    void helpIncrement() {
        if (day < daysInMonth(month, year)) {
            ++day;
        } else {
            day = 1;
            if (month < 12) {
                ++month;
            } else {
                month = 1;
                ++year;
            }
        }
    }

public:
    SimpleDate(int m = 1, int d = 1, int y = 2000) : month(m), day(d), year(y) {}

    // Prefix increment: modifies and returns reference (*this)
    SimpleDate& operator++() {
        helpIncrement();
        return *this;
    }

    // Postfix increment: returns copy of previous state by value
    SimpleDate operator++(int) {
        SimpleDate temp = *this;
        helpIncrement();
        return temp;
    }

    friend std::ostream& operator<<(std::ostream& os, const SimpleDate& d) {
        static const std::string months[] = {
            "", "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };
        os << months[d.month] << " " << d.day << ", " << d.year;
        return os;
    }
};

int main() {
    SimpleDate d1(2, 28, 2008); // 2008 is leap year
    std::cout << "Initial d1: " << d1 << "\n";
    std::cout << "++d1: " << ++d1 << "\n";
    std::cout << "After prefix: " << d1 << "\n\n";

    SimpleDate d2(7, 13, 2010);
    std::cout << "Initial d2: " << d2 << "\n";
    std::cout << "d2++: " << d2++ << "\n";
    std::cout << "After postfix: " << d2 << "\n";
    return 0;
}

#include <iostream>

class Counter {
private:
    int id;
public:
    Counter() : id(0) {
        std::cout << "Counter default constructed (" << id << ")\n";
    }
    Counter(int val) : id(val) {
        std::cout << "Counter constructed with id: " << id << "\n";
    }
    ~Counter() {
        std::cout << "Counter destructed id: " << id << "\n";
    }
    int getId() const { return id; }
};

int main() {
    // 1. Dynamic allocation of a fundamental type with an initializer
    double *piPtr = new double(3.14159);
    std::cout << "Value of *piPtr: " << *piPtr << "\n";
    delete piPtr;
    piPtr = nullptr; // Defensive programming

    // 2. Dynamic allocation of an object
    Counter *cPtr = new Counter(42);
    std::cout << "Object id: " << cPtr->getId() << "\n";
    delete cPtr;
    cPtr = nullptr;

    // Safe to delete nullptr
    delete cPtr;

    // 3. Dynamic array with value-initialization
    const int size = 3;
    int *nums = new int[size](); // all zero-initialized
    std::cout << "nums[0] = " << nums[0] << ", nums[1] = " << nums[1] << "\n";
    delete[] nums;
    nums = nullptr;

    return 0;
}
